const helmet = require('helmet');

// 1. Enforce security headers & hide Express
app.use(helmet());
app.disable('x-powered-by');

// 2. Harden session cookie
app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: true,       // Enforce HTTPS transmission
    httpOnly: true,     // Block XSS access
    sameSite: 'lax',    // Defend against CSRF
    maxAge: 1000 * 60 * 60 * 24 // 24-hour expiration
  }
}));
